import assert from 'node:assert/strict';
import { OrderConsumer } from './src/workers/order_consumer.mjs';
import { DedupStore } from './src/infra/dedup_store.mjs';
import { DlqWriter } from './src/infra/dlq_writer.mjs';
import { LockManager } from './src/infra/lock_manager.mjs';

const lockManager = new LockManager();
const dedupStore = new DedupStore();
const dlq = new DlqWriter();
const consumer = new OrderConsumer({ lockManager, dedupStore, dlq, maxRetries: 3 });

// 1. Normal commit
const res1 = await consumer.consumeOrderEvent({ eventId: 'evt-1', orderId: 'ord-1', retryCount: 0 });
assert.deepEqual(res1, { processed: true, status: 'COMMITTED', orderId: 'ord-1' });
assert.equal(lockManager.held.size, 0);

// 2. Duplicate ignored
const res2 = await consumer.consumeOrderEvent({ eventId: 'evt-1', orderId: 'ord-1', retryCount: 0 });
assert.deepEqual(res2, { processed: false, status: 'DUPLICATE_IGNORED' });

// 3. Dead letter on maxRetries
const dlqEvt = { eventId: 'evt-2', orderId: 'ord-2', retryCount: 3 };
const res3 = await consumer.consumeOrderEvent(dlqEvt);
assert.deepEqual(res3, { processed: false, status: 'DEAD_LETTER' });
assert.deepEqual(dlq.messages, [{ event: dlqEvt, reasonCode: 'MAX_RETRIES_EXCEEDED' }]);
assert.equal(lockManager.held.size, 0);

// 4. Lock busy
await lockManager.tryLease({ resourceKey: 'ord-3', ttlMs: 5000 });
const res4 = await consumer.consumeOrderEvent({ eventId: 'evt-3', orderId: 'ord-3', retryCount: 0 });
assert.deepEqual(res4, { processed: false, status: 'LOCK_BUSY' });
await lockManager.releaseLease({ resourceKey: 'ord-3' });

console.log('Integration checks passed!');
""}

